import React, { useState, useEffect } from 'react';
import { CheckCircleIcon, ExclamationTriangleIcon, InformationCircleIcon } from '@heroicons/react/24/outline';
import { useNotification } from '../../hooks/useNotification';

const SPFConfigurationStep = ({ domainId, data, onChange, errors, onNext, onPrev, canGoBack, saving }) => {
  const [spfRecord, setSPFRecord] = useState(data.spfRecord || '');
  const [spfMechanisms, setSPFMechanisms] = useState(data.spfMechanisms || []);
  const [customMechanism, setCustomMechanism] = useState('');
  const [spfPolicy, setSPFPolicy] = useState(data.spfPolicy || 'softfail');
  const [includeServices, setIncludeServices] = useState(data.includeServices || []);
  const { showNotification } = useNotification();

  // Servicios comunes de email
  const emailServices = [
    { id: 'google', name: 'Google Workspace', include: 'include:_spf.google.com' },
    { id: 'microsoft', name: 'Microsoft 365', include: 'include:spf.protection.outlook.com' },
    { id: 'mailchimp', name: 'Mailchimp', include: 'include:servers.mcsv.net' },
    { id: 'sendgrid', name: 'SendGrid', include: 'include:sendgrid.net' },
    { id: 'mailgun', name: 'Mailgun', include: 'include:mailgun.org' },
    { id: 'amazonses', name: 'Amazon SES', include: 'include:amazonses.com' }
  ];

  // Políticas SPF
  const spfPolicies = [
    { value: 'softfail', label: '~all (SoftFail)', description: 'Marcar como sospechoso pero aceptar' },
    { value: 'fail', label: '-all (Fail)', description: 'Rechazar completamente' },
    { value: 'neutral', label: '?all (Neutral)', description: 'No hacer nada específico' },
    { value: 'pass', label: '+all (Pass)', description: 'Aceptar todo (no recomendado)' }
  ];

  useEffect(() => {
    generateSPFRecord();
  }, [spfMechanisms, spfPolicy, includeServices]);

  useEffect(() => {
    // Actualizar datos del paso cuando cambien los valores
    onChange('spfRecord', spfRecord);
    onChange('spfMechanisms', spfMechanisms);
    onChange('spfPolicy', spfPolicy);
    onChange('includeServices', includeServices);
  }, [spfRecord, spfMechanisms, spfPolicy, includeServices]);

  const generateSPFRecord = () => {
    let record = 'v=spf1';

    // Agregar servicios incluidos
    includeServices.forEach(serviceId => {
      const service = emailServices.find(s => s.id === serviceId);
      if (service) {
        record += ` ${service.include}`;
      }
    });

    // Agregar mecanismos personalizados
    spfMechanisms.forEach(mechanism => {
      record += ` ${mechanism}`;
    });

    // Agregar política final
    const policy = spfPolicies.find(p => p.value === spfPolicy);
    if (policy) {
      record += ` ${policy.label.split(' ')[0]}`;
    }

    setSPFRecord(record);
  };

  const addMechanism = () => {
    if (customMechanism.trim()) {
      setSPFMechanisms([...spfMechanisms, customMechanism.trim()]);
      setCustomMechanism('');
    }
  };

  const removeMechanism = (index) => {
    setSPFMechanisms(spfMechanisms.filter((_, i) => i !== index));
  };

  const toggleService = (serviceId) => {
    if (includeServices.includes(serviceId)) {
      setIncludeServices(includeServices.filter(id => id !== serviceId));
    } else {
      setIncludeServices([...includeServices, serviceId]);
    }
  };

  const validateSPFRecord = (record) => {
    const issues = [];

    if (!record.startsWith('v=spf1')) {
      issues.push('El registro debe comenzar con "v=spf1"');
    }

    if (record.length > 255) {
      issues.push('El registro SPF es demasiado largo (máximo 255 caracteres)');
    }

    const includeCount = (record.match(/include:/g) || []).length;
    if (includeCount > 10) {
      issues.push('Demasiados mecanismos "include" (máximo recomendado: 10)');
    }

    if (!record.includes('all')) {
      issues.push('El registro debe terminar con una política "all"');
    }

    return issues;
  };

  const spfValidation = validateSPFRecord(spfRecord);
  const isValid = spfValidation.length === 0;

  const handleNext = () => {
    if (isValid && spfRecord) {
      onNext();
    } else {
      showNotification('Por favor corrige los errores en el registro SPF', 'error');
    }
  };

  return (
    <div className="space-y-6">
      {/* Introducción */}
      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
        <div className="flex items-start">
          <div className="flex-shrink-0">
            <InformationCircleIcon className="h-5 w-5 text-blue-400" />
          </div>
          <div className="ml-3">
            <h3 className="text-sm font-medium text-blue-800">
              Configuración del Registro SPF
            </h3>
            <div className="mt-2 text-sm text-blue-700">
              <p>
                SPF (Sender Policy Framework) especifica qué servidores están autorizados
                a enviar correos en nombre de tu dominio.
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Servicios de email */}
      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Servicios de Email</h3>
        <p className="text-sm text-gray-600 mb-4">
          Selecciona los servicios de email que utilizas para enviar correos desde tu dominio:
        </p>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          {emailServices.map(service => (
            <label key={service.id} className="flex items-center p-3 border border-gray-200 rounded-lg hover:bg-gray-50 cursor-pointer">
              <input
                type="checkbox"
                checked={includeServices.includes(service.id)}
                onChange={() => toggleService(service.id)}
                className="h-4 w-4 text-primary-600 focus:ring-primary-500 border-gray-300 rounded"
              />
              <div className="ml-3">
                <div className="text-sm font-medium text-gray-900">{service.name}</div>
                <div className="text-xs text-gray-500 font-mono">{service.include}</div>
              </div>
            </label>
          ))}
        </div>
      </div>

      {/* Mecanismos personalizados */}
      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Mecanismos Personalizados</h3>
        <p className="text-sm text-gray-600 mb-4">
          Agrega mecanismos SPF adicionales como direcciones IP o dominios específicos:
        </p>

        <div className="flex space-x-2 mb-4">
          <input
            type="text"
            value={customMechanism}
            onChange={(e) => setCustomMechanism(e.target.value)}
            placeholder="ej: ip4:192.168.1.1 o include:mail.example.com"
            className="flex-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm"
            onKeyPress={(e) => e.key === 'Enter' && addMechanism()}
          />
          <button
            onClick={addMechanism}
            disabled={!customMechanism.trim()}
            className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            Agregar
          </button>
        </div>

        {spfMechanisms.length > 0 && (
          <div className="space-y-2">
            {spfMechanisms.map((mechanism, index) => (
              <div key={index} className="flex items-center justify-between p-2 bg-gray-50 rounded-md">
                <span className="text-sm font-mono">{mechanism}</span>
                <button
                  onClick={() => removeMechanism(index)}
                  className="text-red-600 hover:text-red-800 text-sm"
                >
                  Eliminar
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Política SPF */}
      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Política SPF</h3>
        <p className="text-sm text-gray-600 mb-4">
          Selecciona qué hacer con los correos que no coincidan con tu registro SPF:
        </p>

        <div className="space-y-3">
          {spfPolicies.map(policy => (
            <label key={policy.value} className="flex items-start p-3 border border-gray-200 rounded-lg hover:bg-gray-50 cursor-pointer">
              <input
                type="radio"
                name="spfPolicy"
                value={policy.value}
                checked={spfPolicy === policy.value}
                onChange={(e) => setSPFPolicy(e.target.value)}
                className="h-4 w-4 text-primary-600 focus:ring-primary-500 border-gray-300 mt-0.5"
              />
              <div className="ml-3">
                <div className="text-sm font-medium text-gray-900">{policy.label}</div>
                <div className="text-sm text-gray-600">{policy.description}</div>
              </div>
            </label>
          ))}
        </div>
      </div>

      {/* Registro SPF generado */}
      <div className="bg-white border border-gray-200 rounded-lg p-4">
        <h3 className="text-lg font-medium text-gray-900 mb-4">Registro SPF Generado</h3>

        <div className="bg-gray-50 border border-gray-200 rounded-md p-3 mb-4">
          <div className="text-sm text-gray-600 mb-2">Tipo: TXT</div>
          <div className="text-sm text-gray-600 mb-2">Nombre: @ (o tu dominio)</div>
          <div className="text-sm text-gray-600 mb-2">Valor:</div>
          <div className="font-mono text-sm bg-white border border-gray-200 rounded p-2 break-all">
            {spfRecord}
          </div>
        </div>

        {/* Validación */}
        {spfValidation.length > 0 ? (
          <div className="bg-red-50 border border-red-200 rounded-lg p-3">
            <div className="flex">
              <ExclamationTriangleIcon className="h-5 w-5 text-red-400 flex-shrink-0" />
              <div className="ml-3">
                <h4 className="text-sm font-medium text-red-800">Problemas Detectados</h4>
                <ul className="mt-2 text-sm text-red-700 list-disc list-inside">
                  {spfValidation.map((issue, index) => (
                    <li key={index}>{issue}</li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        ) : (
          <div className="bg-green-50 border border-green-200 rounded-lg p-3">
            <div className="flex">
              <CheckCircleIcon className="h-5 w-5 text-green-400 flex-shrink-0" />
              <div className="ml-3">
                <h4 className="text-sm font-medium text-green-800">Registro SPF Válido</h4>
                <p className="mt-1 text-sm text-green-700">
                  El registro SPF está correctamente formateado y listo para usar.
                </p>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Instrucciones */}
      <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
        <div className="flex">
          <InformationCircleIcon className="h-5 w-5 text-yellow-400 flex-shrink-0" />
          <div className="ml-3">
            <h3 className="text-sm font-medium text-yellow-800">
              Instrucciones de Implementación
            </h3>
            <div className="mt-2 text-sm text-yellow-700">
              <ol className="list-decimal list-inside space-y-1">
                <li>Accede al panel de control de tu proveedor de DNS</li>
                <li>Crea un nuevo registro TXT para tu dominio</li>
                <li>Copia y pega el valor del registro SPF generado</li>
                <li>Guarda los cambios y espera a que se propaguen (puede tomar hasta 24 horas)</li>
              </ol>
            </div>
          </div>
        </div>
      </div>

      {/* Error de validación */}
      {errors.spfRecord && (
        <div className="text-sm text-red-600">
          {errors.spfRecord}
        </div>
      )}

      {/* Botones de navegación */}
      <div className="flex justify-between pt-6">
        <button
          onClick={onPrev}
          disabled={!canGoBack}
          className="inline-flex items-center px-4 py-2 border border-gray-300 shadow-sm text-sm font-medium rounded-md text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Anterior
        </button>

        <button
          onClick={handleNext}
          disabled={saving || !isValid || !spfRecord}
          className="inline-flex items-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed"
        >
          {saving ? 'Guardando...' : 'Siguiente'}
        </button>
      </div>
    </div>
  );
};

export default SPFConfigurationStep;
